'use strict';
// ============================================================
//  Jerry Mod Test Chams — API Server
//  Chạy: node server.js
//  DB:   SQLite (tự tạo jerry.db cùng thư mục)
// ============================================================
const express    = require('express');
const cors       = require('cors');
const bcrypt     = require('bcryptjs');
const jwt        = require('jsonwebtoken');
const path       = require('path');
const fs         = require('fs');
const { domainToASCII } = require('node:url');
const { DatabaseSync } = require('node:sqlite');
const { randomInt, randomUUID, createHmac } = require('crypto');

const PORT           = Number(process.env.PORT || 3000);
const RESET_SECRET   = requiredSecret('RESET_SECRET');
// Chỉ cần một Railway secret. Hai khóa JWT được dẫn xuất riêng trong server,
// không cần thêm biến môi trường và không bao giờ gửi xuống client.
const ACCESS_SECRET  = createHmac('sha256', RESET_SECRET).update('jerry-chams-access-v1').digest('hex');
const REFRESH_SECRET = createHmac('sha256', RESET_SECRET).update('jerry-chams-refresh-v1').digest('hex');
const PUBLIC_DIR     = path.join(__dirname, 'public');
const DATA_DIR       = process.env.DATA_DIR || process.env.RAILWAY_VOLUME_MOUNT_PATH || __dirname;
const DB_PATH        = process.env.DB_PATH || path.join(DATA_DIR, 'jerry.db');
const MAX_UPLOAD_BYTES = Math.max(1, Number(process.env.MAX_UPLOAD_MB || 25)) * 1024 * 1024;
const KEY_PREFIX     = 'MAKEDNS-';
const KEY_FORMAT     = /^MAKEDNS-[A-Z0-9]{8}$/;

function requiredSecret(name) {
  const value = process.env[name];
  if (!value || value.length < 32) {
    throw new Error(`${name} must be set to a random value of at least 32 characters`);
  }
  return value;
}

