// ── SQLite ────────────────────────────────────────────────────
fs.mkdirSync(DATA_DIR, { recursive: true });
const db = new DatabaseSync(DB_PATH);
db.exec('PRAGMA journal_mode = WAL');
db.exec(`
  CREATE TABLE IF NOT EXISTS admins (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
  CREATE TABLE IF NOT EXISTS keys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    value TEXT NOT NULL UNIQUE,
    type TEXT NOT NULL DEFAULT 'FREE',
    active INTEGER NOT NULL DEFAULT 1,
    expiry INTEGER NOT NULL DEFAULT -1,
    days_duration INTEGER NOT NULL DEFAULT 0,
    max_devices INTEGER NOT NULL DEFAULT 1,
    max_uses INTEGER NOT NULL DEFAULT 0,
    uses INTEGER NOT NULL DEFAULT 0,
    note TEXT NOT NULL DEFAULT '',
    tool_type TEXT NOT NULL DEFAULT 'Make Cham',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
  CREATE TABLE IF NOT EXISTS devices (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    key_id INTEGER NOT NULL,
    fingerprint TEXT NOT NULL,
    ip TEXT NOT NULL DEFAULT '',
    last_seen TEXT NOT NULL DEFAULT (datetime('now')),
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
  CREATE TABLE IF NOT EXISTS logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    action TEXT NOT NULL,
    key_val TEXT,
    key_id INTEGER,
    success INTEGER NOT NULL DEFAULT 1,
    ip TEXT,
    message TEXT,
    ts TEXT NOT NULL DEFAULT (datetime('now'))
  );
  CREATE TABLE IF NOT EXISTS refresh_tokens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    token TEXT NOT NULL UNIQUE,
    admin_id INTEGER NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
`);

// ── JWT ───────────────────────────────────────────────────────
function signAccess(id, u)   { return jwt.sign({ adminId: id, username: u }, ACCESS_SECRET,  { expiresIn: '15m' }); }
function signRefresh(id)      { return jwt.sign({ adminId: id }, REFRESH_SECRET, { expiresIn: '30d' }); }
function verifyAccess(tok)    { try { return jwt.verify(tok, ACCESS_SECRET);  } catch { return null; } }
function verifyRefresh(tok)   { try { return jwt.verify(tok, REFRESH_SECRET); } catch { return null; } }

function requireAdmin(req, res, next) {
  const h = req.headers.authorization;
  if (!h || !h.startsWith('Bearer ')) return res.status(401).json({ error: 'Unauthorized' });
  const p = verifyAccess(h.slice(7));
  if (!p) return res.status(401).json({ error: 'Token hết hạn hoặc không hợp lệ' });
  req.admin = p; next();
}

// ── Helpers ───────────────────────────────────────────────────
function getIp(req) {
  const f = req.headers['x-forwarded-for'];
  if (f) return (Array.isArray(f) ? f[0] : f.split(',')[0]).trim();
  return req.socket?.remoteAddress ?? 'unknown';
}
function mkFingerprint(req) {
  const raw = (req.headers['user-agent'] ?? '') + '|' + getIp(req) + '|' + (req.headers['accept-language'] ?? '');
  let h = 0;
  for (let i = 0; i < raw.length; i++) { h = (h << 5) - h + raw.charCodeAt(i); h |= 0; }
  return Math.abs(h).toString(16).padStart(8,'0') + '-' + raw.length.toString(16);
}
function randStr(len) {
  const c = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  return Array.from({ length: len }, () => c[randomInt(c.length)]).join('');
}
function addLog(action, opts = {}) {
  db.prepare('INSERT INTO logs (action,key_val,key_id,success,ip,message) VALUES (?,?,?,?,?,?)')
    .run(action, opts.keyVal??null, opts.keyId??null, opts.success??1, opts.ip??null, opts.message??null);
}

function constantTimeEqual(a, b) {
  const left = Buffer.from(String(a || ''));
  const right = Buffer.from(String(b || ''));
  return left.length === right.length && require('crypto').timingSafeEqual(left, right);
}

// ── Patch engine (find + replace bytes in binary) ─────────────
function hexToBytes(hex) {
  const s = hex.replace(/[^0-9A-Fa-f]/g,'');
  if (s.length % 2 !== 0) return null;
  const b = Buffer.allocUnsafe(s.length / 2);
  for (let i = 0; i < s.length; i += 2) b[i >> 1] = parseInt(s.substr(i,2),16);
  return b;
}
function applyHexPatch(buf, findHex, replaceHex) {
  const search  = hexToBytes(findHex);
  const replace = Buffer.isBuffer(replaceHex) ? replaceHex : hexToBytes(replaceHex);
  if (!search || !replace) return 0;
  let count = 0;
  for (let i = 0; i <= buf.length - search.length; i++) {
    let ok = true;
    for (let j = 0; j < search.length; j++) if (buf[i+j] !== search[j]) { ok=false; break; }
    if (ok) {
      const wl = Math.min(replace.length, buf.length - i);
      replace.copy(buf, i, 0, wl); count++; i += wl - 1;
    }
  }
  return count;
}

const ENGINE_PROPERTIES = [
  { text: '_Color', len: 6 },
  { text: '_MainTex', len: 8 },
  { text: '_MaskColor', len: 10 },
  { text: '_XRayColor', len: 10 },
  { text: '_OutLineColor', len: 13 },
  { text: '_OutLineWidth', len: 13 },
  { text: '_Ambientlight', len: 13 },
  { text: '_StretchRatio', len: 13 },
  { text: '_AlphaMask', len: 10 },
  { text: '_CharaSpectatorColor', len: 20 },
];
let engineConfigCache = null;

function readEngineConfig() {
  if (engineConfigCache) return engineConfigCache;
  const template = hexToBytes(EMBEDDED_COLOR_HEX);
  const fields = [];
  for (const prop of ENGINE_PROPERTIES) {
    let from = 0;
    const needle = Buffer.from(prop.text, 'ascii');
    while (from <= template.length - needle.length) {
      const pos = template.indexOf(needle, from);
      if (pos < 0) break;
      from = pos + 1;
      if (pos < 4 || template.readUInt32LE(pos - 4) !== prop.len) continue;
      let p = pos + prop.len;
      p += (4 - (prop.len % 4)) % 4;
      if (p + 4 > template.length) continue;
      const descLen = template.readUInt32LE(p); p += 4;
      if (descLen > 100 || p + descLen > template.length) continue;
      const desc = template.subarray(p, p + descLen).toString('ascii'); p += descLen;
      p += (4 - (descLen % 4)) % 4;
      if (p + 28 > template.length) continue;
      const type = template.readUInt32LE(p + 4);
      if (type !== 0 && type !== 2) continue;
      const label = prop.text === '_XRayColor' ? 'MÀU NHÂN VẬT'
        : prop.text === '_OutLineColor' ? 'MÀU VIỀN'
        : prop.text === '_OutLineWidth' ? 'ĐỘ DÀY VIỀN'
        : desc;
      if (type === 2) {
        fields.push({ id: `${fields.length}`, label, kind: 'float', value: template.readFloatLE(p + 12), min: 0, max: 50, step: 0.1 });
      } else {
        const rgba = [0, 1, 2, 3].map(i => template.readFloatLE(p + i * 4));
        fields.push({ id: `${fields.length}`, label, kind: 'color', value: rgbaToHex(rgba) });
      }
    }
  }
  engineConfigCache = fields;
  return fields;
}

function rgbaToHex(rgba) {
  return '#' + rgba.map(value => Math.max(0, Math.min(255, Math.round(value * 255)))
    .toString(16).padStart(2, '0').toUpperCase()).join('');
}

function hexToRgba(value) {
  const clean = String(value || '').replace(/^#/, '');
  if (!/^[0-9a-fA-F]{6}([0-9a-fA-F]{2})?$/.test(clean)) return null;
  const full = clean.length === 6 ? clean + 'FF' : clean;
  return [0, 1, 2, 3].map(i => parseInt(full.slice(i * 2, i * 2 + 2), 16) / 255);
}

function buildReplacementTemplate(changes) {
  const template = hexToBytes(EMBEDDED_COLOR_HEX);
  const fields = readEngineConfig();
  if (!changes || typeof changes !== 'object' || Array.isArray(changes)) return null;
  for (const [id, value] of Object.entries(changes)) {
    const field = fields.find(item => item.id === id);
    if (!field) return null;
    if (field.kind === 'float') {
      const numeric = Number(value);
      if (!Number.isFinite(numeric) || numeric < 0 || numeric > 50) return null;
      let seen = 0;
      let floatOffset = -1;
      for (const candidate of ENGINE_PROPERTIES) {
        const needle = Buffer.from(candidate.text, 'ascii');
        for (let pos = 0; pos <= template.length - needle.length; pos++) {
          if (!template.subarray(pos, pos + needle.length).equals(needle)) continue;
          if (pos < 4 || template.readUInt32LE(pos - 4) !== candidate.len) continue;
          let p = pos + candidate.len;
          p += (4 - (candidate.len % 4)) % 4;
          if (p + 4 > template.length) continue;
          const descLen = template.readUInt32LE(p); p += 4;
          if (descLen > 100 || p + descLen > template.length) continue;
          p += descLen + ((4 - (descLen % 4)) % 4);
          if (p + 16 > template.length) continue;
          const candidateType = template.readUInt32LE(p + 4);
          if (candidateType !== 0 && candidateType !== 2) continue;
          if (candidateType === 2 && String(seen) === id) { floatOffset = p + 12; break; }
          seen++;
        }
        if (floatOffset >= 0) break;
      }
      if (floatOffset < 0) return null;
      template.writeFloatLE(numeric, floatOffset);
      continue;
    }
    const rgba = hexToRgba(value);
    if (!rgba) return null;
    // Field IDs are generated in scan order. Re-scan and use the matching index.
    let seen = 0;
    let offset = -1;
    for (const candidate of ENGINE_PROPERTIES) {
      const needle = Buffer.from(candidate.text, 'ascii');
      for (let pos = 0; pos <= template.length - needle.length; pos++) {
        if (!template.subarray(pos, pos + needle.length).equals(needle)) continue;
        if (pos < 4 || template.readUInt32LE(pos - 4) !== candidate.len) continue;
        let p = pos + candidate.len;
        p += (4 - (candidate.len % 4)) % 4;
        if (p + 4 > template.length) continue;
        const descLen = template.readUInt32LE(p); p += 4;
        if (descLen > 100 || p + descLen > template.length) continue;
        p += descLen + ((4 - (descLen % 4)) % 4);
        if (p + 16 > template.length) continue;
        const candidateType = template.readUInt32LE(p + 4);
        if (candidateType !== 0) { if (candidateType === 2) seen++; continue; }
        if (String(seen) === id) { offset = p + 12; break; }
        seen++;
      }
      if (offset >= 0) break;
    }
    if (offset < 0) return null;
    rgba.forEach((component, index) => template.writeFloatLE(component, offset + index * 4));
  }
  return template;
}

// ── Download store (temp, 5 min) ──────────────────────────────
const downloadStore = new Map();
const licenseSessions = new Map();
setInterval(() => { const now=Date.now(); for(const [id,e] of downloadStore) if(e.expiry<now) downloadStore.delete(id); }, 60_000);
setInterval(() => {
  const now = Date.now();
  for (const [token, session] of licenseSessions) {
    if (session.expiresAt <= now) licenseSessions.delete(token);
  }
}, 60_000);

function createLicenseSession(key, deviceId) {
  const token = randomUUID() + randomUUID().replaceAll('-', '');
  licenseSessions.set(token, {
    keyId: key.id,
    deviceId,
    expiresAt: Date.now() + 15 * 60 * 1000,
  });
  return token;
}

function getLicenseSession(req) {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return null;
  const session = licenseSessions.get(header.slice(7));
  if (!session || session.expiresAt <= Date.now()) return null;
  const key = db.prepare('SELECT * FROM keys WHERE id=?').get(session.keyId);
  if (!key) return null;
  session.expiresAt = Date.now() + 15 * 60 * 1000;
  return { ...session, key };
}

function requireLicense(req, res, next) {
  const session = getLicenseSession(req);
  if (!session) return res.status(401).json({ error: 'Phiên key đã hết hạn, hãy nhập lại key.' });
  const resolved = resolveKey(session.key.value, { ignoreUseLimit: true });
  if (!resolved.ok) return res.status(resolved.status).json({ error: resolved.error });
  req.license = { ...session, key: resolved.key };
  next();
}

// ── NextDNS + mobileconfig builder ────────────────────────────
function parseDomainList(input) {
  const domains = [];
  const seen = new Set();
  for (const line of String(input || '').split(/\r?\n/)) {
    for (let token of line.split(/[\s,;]+/)) {
      const original = token.trim();
      token = original.toLowerCase().replace(/\.$/, '');
      token = token.replace(/^https?:\/\//i, '').split(/[/?#]/, 1)[0];
      if (token && !seen.has(token)) {
        seen.add(token);
        domains.push(token);
      }
    }
  }
  return domains;
}

function normalizeNextDnsDomain(domain, listName) {
  // Khớp với giao diện NextDNS: bỏ wildcard ở denylist rồi chuyển IDN sang
  // ASCII/Punycode. domainToASCII cũng loại một số ký tự định dạng vô hình
  // thường bị dính khi copy/paste. Giữ bản gốc để NextDNS trả lỗi cụ thể nếu
  // giá trị vẫn không hợp lệ.
  let normalized = String(domain || '').trim().toLowerCase().replace(/\.$/, '');
  if (listName === 'denylist') normalized = normalized.replace(/^\*\./, '');
  return domainToASCII(normalized) || normalized;
}

async function nextDnsRequest(apiKey, endpoint, method = 'GET', body) {
  const response = await fetch('https://api.nextdns.io' + endpoint, {
    method,
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      'X-Api-Key': apiKey,
      'User-Agent': 'railway-nextdns-manager/1.0',
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const raw = await response.text();
  let data = {};
  try { data = raw ? JSON.parse(raw) : {}; } catch {
    throw new Error('NextDNS trả về dữ liệu không hợp lệ.');
  }
  if (!response.ok || data.errors) {
    const errors = Array.isArray(data.errors) ? data.errors : [];
    const detail = errors.map(item => item?.detail || item?.title || JSON.stringify(item)).join('; ');
    throw new Error(`NextDNS HTTP ${response.status}: ${detail || 'yêu cầu bị từ chối'}`);
  }
  return data.data ?? data;
}

async function updateNextDnsList(apiKey, profileId, listName, domains) {
  if (!domains.length) return { added: 0, skipped: 0, rejected: [] };
  const encodedId = encodeURIComponent(profileId);
  const currentData = await nextDnsRequest(apiKey, `/profiles/${encodedId}/${listName}`);
  const current = new Set(
    (Array.isArray(currentData) ? currentData : currentData?.items || [])
      .map(entry => normalizeNextDnsDomain(entry?.id || '', listName))
  );
  let added = 0;
  let skipped = 0;
  const rejected = [];
  for (const rawDomain of domains) {
    const domain = normalizeNextDnsDomain(rawDomain, listName);
    if (current.has(domain)) {
      skipped++;
      continue;
    }
    try {
      await nextDnsRequest(apiKey, `/profiles/${encodedId}/${listName}`, 'POST', {
        id: domain,
        active: true,
      });
      current.add(domain);
      added++;
    } catch (error) {
      // Một miền lỗi không được làm dừng cả danh sách. Giữ nguyên lỗi
      // NextDNS để giao diện hiển thị đúng cho người dùng.
      rejected.push({ domain, error: error?.message || 'NextDNS từ chối yêu cầu' });
    }
  }
  return { added, skipped, rejected };
}

function xmlEscape(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&apos;');
}

function replacePlistValue(xml, key, value) {
  const expression = new RegExp(
    `(<key>${key}</key>\\s*<string>)[\\s\\S]*?(</string>)`,
    'i'
  );
  let replaced = false;
  const output = xml.replace(expression, (_match, prefix, suffix) => {
    replaced = true;
    return prefix + xmlEscape(value) + suffix;
  });
  return { output, replaced };
}

function replaceMobileConfigIdentity(xml, name, description, profileId) {
  let result = xml;
  let nameReplaced = false;
  let descriptionReplaced = false;

  for (const marker of ['{{CONFIG_NAME}}', '__CONFIG_NAME__', '%%CONFIG_NAME%%']) {
    if (result.includes(marker)) {
      result = result.replaceAll(marker, xmlEscape(name));
      nameReplaced = true;
    }
  }
  for (const marker of ['{{CONFIG_DESCRIPTION}}', '__CONFIG_DESCRIPTION__', '%%CONFIG_DESCRIPTION%%']) {
    if (result.includes(marker)) {
      result = result.replaceAll(marker, xmlEscape(description));
      descriptionReplaced = true;
    }
  }
  const nameResult = replacePlistValue(result, 'PayloadDisplayName', name);
  result = nameResult.output;
  nameReplaced ||= nameResult.replaced;
  const descriptionResult = replacePlistValue(result, 'PayloadDescription', description);
  result = descriptionResult.output;
  descriptionReplaced ||= descriptionResult.replaced;

  let profileIdReplacements = 0;
  for (const marker of ['{{NEXTDNS_ID}}', '__NEXTDNS_ID__', '%%NEXTDNS_ID%%', '{{PROFILE_ID}}', '__PROFILE_ID__']) {
    const occurrences = result.split(marker).length - 1;
    if (occurrences) {
      result = result.replaceAll(marker, profileId);
      profileIdReplacements += occurrences;
    }
  }
  result = result.replace(/(\.antiban\.)([A-Za-z0-9_-]+)/gi, (_match, prefix) => {
    profileIdReplacements++;
    return prefix + profileId;
  });
  result = result.replace(/(https?:\/\/[^\s<>"']*nextdns\.io\/)[^\s<>"']+/gi, (_match, prefix) => {
    profileIdReplacements++;
    return prefix + profileId;
  });

  return { result, nameReplaced, descriptionReplaced, profileIdReplacements };
}

function safeMobileConfigFilename(name) {
  const clean = String(name || 'nextdns-profile')
    .normalize('NFKD')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-')
    .slice(0, 80);
  return (clean || 'nextdns-profile') + '.mobileconfig';
}

