app.post('/api/auth/setup', async (req,res) => {
  if (db.prepare('SELECT id FROM admins LIMIT 1').get()) return res.status(403).json({ error:'Admin đã được thiết lập' });
  const { username, password } = req.body;
  if (!username||!password) return res.status(400).json({ error:'Thiếu username hoặc password' });
  const hash = await bcrypt.hash(password, 12);
  db.prepare('INSERT INTO admins (username,password_hash) VALUES (?,?)').run(username, hash);
  res.json({ ok:true, username });
});

app.post('/api/auth/login', async (req,res) => {
  const { username, password } = req.body;
  if (!username||!password) return res.status(400).json({ error:'Thiếu thông tin đăng nhập' });
  const admin = db.prepare('SELECT * FROM admins WHERE username=?').get(username);
  if (!admin || !(await bcrypt.compare(password, admin.password_hash)))
    return res.status(401).json({ error:'Sai tên đăng nhập hoặc mật khẩu' });
  const at = signAccess(admin.id, admin.username);
  const rt = signRefresh(admin.id);
  db.prepare('INSERT INTO refresh_tokens (token,admin_id,expires_at) VALUES (?,?,?)').run(rt, admin.id, new Date(Date.now()+30*864e5).toISOString());
  res.json({ accessToken:at, refreshToken:rt });
});

app.post('/api/auth/reset-password', async (req,res) => {
  const { reset_token, new_password } = req.body;
  if (!reset_token || !constantTimeEqual(reset_token, RESET_SECRET)) return res.status(403).json({ error:'Mã reset sai' });
  if (!new_password||new_password.length<6) return res.status(400).json({ error:'Mật khẩu phải ít nhất 6 ký tự' });
  const hash = await bcrypt.hash(new_password, 12);
  db.prepare('UPDATE admins SET password_hash=? WHERE id=(SELECT MIN(id) FROM admins)').run(hash);
  db.prepare('DELETE FROM refresh_tokens').run();
  res.json({ ok:true });
});

app.post('/api/auth/refresh', (req,res) => {
  const { refreshToken } = req.body;
  if (!refreshToken) return res.status(400).json({ error:'Thiếu refresh token' });
  const p = verifyRefresh(refreshToken);
  if (!p) return res.status(401).json({ error:'Refresh token không hợp lệ' });
  const stored = db.prepare('SELECT * FROM refresh_tokens WHERE token=?').get(refreshToken);
  if (!stored||new Date(stored.expires_at)<new Date()) return res.status(401).json({ error:'Refresh token hết hạn' });
  const admin = db.prepare('SELECT * FROM admins WHERE id=?').get(p.adminId);
  if (!admin) return res.status(401).json({ error:'Admin không tồn tại' });
  res.json({ accessToken: signAccess(admin.id, admin.username) });
});

app.post('/api/auth/logout', (req,res) => {
  if (req.body.refreshToken) db.prepare('DELETE FROM refresh_tokens WHERE token=?').run(req.body.refreshToken);
  res.json({ ok:true });
});

