app.get('/api/keys', requireAdmin, (req,res) => {
  const filter=req.query.filter??'all', q=(req.query.q??'').toLowerCase(), now=Date.now();
  let rows=db.prepare('SELECT * FROM keys ORDER BY id DESC').all();
  if (q) rows=rows.filter(k=>k.value.toLowerCase().includes(q)||k.note.toLowerCase().includes(q));
  if (filter==='active') rows=rows.filter(k=>k.active&&(k.expiry===0||k.expiry===-1||k.expiry>now));
  if (filter==='locked') rows=rows.filter(k=>!k.active||(k.expiry>0&&k.expiry<=now));
  const devMap=Object.fromEntries(db.prepare('SELECT key_id,COUNT(*) as cnt FROM devices GROUP BY key_id').all().map(d=>[d.key_id,d.cnt]));
  res.json({ keys: rows.map(k=>({ id:k.id,v:k.value,t:k.type,a:!!k.active,e:k.expiry,days_duration:k.days_duration,mu:k.max_uses,u:k.uses,md:k.max_devices,deviceCount:devMap[k.id]??0,note:k.note })) });
});

app.post('/api/keys', requireAdmin, (req,res) => {
  const { prefix=KEY_PREFIX, type='FREE', randLen=8, days=0, count=1, maxDevices=1, maxUses=0, note='' } = req.body;
  if (String(prefix).toUpperCase() !== KEY_PREFIX || Number(randLen) !== 8) {
    return res.status(400).json({ error:'Key phải giữ đúng định dạng MAKEDNS-XXXXXXXX' });
  }
  const safeCount=Math.min(Math.max(+count,1),50), safeLen=8;
  const keyType = type === 'VIP' ? 'VIP' : 'FREE';
  const daysDuration=Math.min(Math.max(Number(days) || 0, 0), 3650);
  const safeDevices=Math.min(Math.max(Number(maxDevices) || 1, 1), 100);
  const safeUses=Math.min(Math.max(Number(maxUses) || 0, 0), 1_000_000);
  const safeNote=String(note || '').slice(0, 500);
  const expiry=daysDuration>0?-1:0;
  const stmt=db.prepare('INSERT INTO keys (value,type,active,expiry,days_duration,max_devices,max_uses,note,tool_type) VALUES (?,?,1,?,?,?,?,?,?)');
  const created=[];
  for (let i=0;i<safeCount;i++) {
    let v;
    do { v=KEY_PREFIX+randStr(safeLen); } while (db.prepare('SELECT 1 FROM keys WHERE value=?').get(v));
    stmt.run(v,keyType,expiry,daysDuration,safeDevices,safeUses,safeNote,'Make Cham');
    created.push({v});
  }
  addLog('Tạo '+safeCount+' key', {ip:getIp(req), message:'Loại: '+keyType+', Hạn: '+daysDuration+' ngày'});
  res.json({ success:true, created });
});

