// ── KEY VALIDATION ─────────────────────────────────────────────
function resolveKey(keyVal, options = {}) {
  const normalized = String(keyVal || '').trim().toUpperCase();
  if (!KEY_FORMAT.test(normalized)) {
    return { ok:false, status:403, error:'Mã khóa không tồn tại hoặc sai định dạng!' };
  }
  const key = db.prepare('SELECT * FROM keys WHERE value=?').get(normalized);
  if (!key)        return { ok:false, status:403, error:'Mã khóa không tồn tại hoặc sai định dạng!' };
  if (!key.active) return { ok:false, status:403, error:'Giấy phép bị quản trị viên khóa!' };
  if (key.expiry>0 && Date.now()>key.expiry) return { ok:false, status:403, error:'Giấy phép đã hết hạn!' };
  if (!options.ignoreUseLimit && key.max_uses>0 && key.uses>=key.max_uses) {
    return { ok:false, status:403, error:'Key đã đạt giới hạn lượt sử dụng!' };
  }
  return { ok:true, key };
}

// Validate key — trả về colorHex để client khởi tạo color engine
app.post('/api/validate-key', (req,res) => {
  const { key:keyVal, deviceId } = req.body;
  if (!keyVal) return res.status(400).json({ success:false, error:'Thiếu mã key' });

  const ip=getIp(req);
  // Nếu client gửi deviceId hợp lệ → dùng deviceId (không đổi theo IP)
  // Nếu không (HTML cũ / Netlify chưa update) → fallback về fingerprint IP
  const fp = (deviceId && KEY_FORMAT.test(String(deviceId).toUpperCase()))
    ? String(deviceId).toUpperCase()
    : mkFingerprint(req);
  const normalizedKey = String(keyVal).trim().toUpperCase();
  const r=resolveKey(normalizedKey);
  if (!r.ok) { addLog('Xác thực key thất bại',{keyVal:normalizedKey,success:0,ip,message:r.error}); return res.status(r.status).json({success:false,error:r.error}); }
  const { key } = r;
  if (key.tool_type!=='Make Cham') return res.status(403).json({success:false,error:'Khóa này dành cho phân hệ khác!'});

  // Lazy start: bắt đầu đếm ngày khi user lần đầu nhập key
  let finalExpiry = key.expiry;
  if (key.expiry===-1 && key.days_duration>0) {
    finalExpiry = Date.now() + key.days_duration * 864e5;
    db.prepare('UPDATE keys SET expiry=? WHERE id=?').run(finalExpiry, key.id);
    addLog('Kích hoạt key lần đầu',{keyVal,keyId:key.id,ip,message:'Hạn: '+key.days_duration+' ngày'});
  }

  // Nhận dạng thiết bị
  const isMakedns = fp.startsWith(KEY_PREFIX);
  const devs = db.prepare('SELECT * FROM devices WHERE key_id=?').all(key.id);

  // Tìm bản ghi khớp fingerprint hiện tại
  let exists = devs.find(d => d.fingerprint === fp);

  if (!exists && isMakedns) {
    // Client mới gửi MAKEDNS ID — kiểm tra xem thiết bị này đã từng đăng ký
    // bằng IP fingerprint cũ (HTML cũ) chưa. Nếu có → nâng cấp sang MAKEDNS ID
    // thay vì tạo slot mới (tránh lỗi vượt giới hạn thiết bị).
    const ipFp = mkFingerprint(req);
    const ipRecord = devs.find(d => d.fingerprint === ipFp);
    if (ipRecord) {
      // Nâng cấp: ghi đè fingerprint cũ bằng MAKEDNS ID
      db.prepare('UPDATE devices SET fingerprint=?,ip=?,last_seen=datetime("now") WHERE id=?')
        .run(fp, ip, ipRecord.id);
      addLog('Nâng cấp device ID', {keyVal, keyId:key.id, ip, message:'IP→'+fp});
      exists = { id: ipRecord.id }; // đánh dấu đã xử lý
    }
  }

  if (!exists) {
    if (devs.length >= key.max_devices) {
      addLog('Xác thực key thất bại',{keyVal,keyId:key.id,success:0,ip,message:'Vượt giới hạn thiết bị ('+fp+')'});
      return res.status(403).json({success:false,error:'Key đã đạt giới hạn '+key.max_devices+' thiết bị! Liên hệ admin để reset thiết bị.'});
    }
    db.prepare('INSERT INTO devices (key_id,fingerprint,ip) VALUES (?,?,?)').run(key.id,fp,ip);
    db.prepare('UPDATE keys SET uses=uses+1 WHERE id=?').run(key.id);
    addLog('Đăng ký thiết bị mới',{keyVal,keyId:key.id,ip,message:'Device: '+fp});
  } else {
    db.prepare("UPDATE devices SET last_seen=datetime('now'),ip=? WHERE id=?").run(ip,exists.id);
  }
  addLog('Xác thực key thành công',{keyVal:normalizedKey,keyId:key.id,ip,message:'Device: '+fp});

  // Không trả raw template/hex bí mật về client. Client chỉ nhận phiên ngắn hạn.
  res.json({
    success:true,
    type:key.type,
    expiry:finalExpiry,
    licenseToken:createLicenseSession(key, fp),
  });
});

// Tạo mobileconfig và cập nhật allowlist/denylist trên NextDNS.
// API key NextDNS chỉ tồn tại trong request tới server, không được lưu DB/log.
app.post('/api/mobileconfig/generate', requireLicense, async (req, res) => {
  const {
    nextDnsApiKey,
    profileId,
    allowlist = '',
    denylist = '',
    configName,
    configDescription,
    templateBase64,
  } = req.body || {};

  const apiKey = String(nextDnsApiKey || '').trim();
  const id = String(profileId || '').trim();
  const name = String(configName || '').trim();
  const description = String(configDescription || '').trim();
  if (!apiKey || !id || !name || !description || !templateBase64) {
    return res.status(400).json({ error: 'Vui lòng nhập đủ API key, NextDNS ID, tên, mô tả và file mẫu.' });
  }
  if (!/^[A-Za-z0-9_-]{6,64}$/.test(id)) {
    return res.status(400).json({ error: 'NextDNS ID không hợp lệ.' });
  }
  if (name.length > 120 || description.length > 500) {
    return res.status(400).json({ error: 'Tên tối đa 120 ký tự, mô tả tối đa 500 ký tự.' });
  }
  if (typeof templateBase64 !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(templateBase64)) {
    return res.status(400).json({ error: 'File mobileconfig không hợp lệ.' });
  }

  const allow = parseDomainList(allowlist);
  const deny = parseDomainList(denylist);
  if (allow.length > 500 || deny.length > 500) {
    return res.status(400).json({ error: 'Mỗi danh sách tối đa 500 miền.' });
  }

  let template;
  try {
    const templateBuffer = Buffer.from(templateBase64, 'base64');
    if (!templateBuffer.length || templateBuffer.length > MAX_UPLOAD_BYTES) {
      return res.status(413).json({ error: `File vượt giới hạn ${Math.floor(MAX_UPLOAD_BYTES / 1024 / 1024)} MB` });
    }
    template = templateBuffer.toString('utf8');
  } catch {
    return res.status(400).json({ error: 'Không thể đọc file mobileconfig.' });
  }
  if (!template.includes('<plist') && !template.includes('<?xml')) {
    return res.status(400).json({ error: 'File mẫu phải là mobileconfig XML hợp lệ.' });
  }

  try {
    const profilesData = await nextDnsRequest(apiKey, '/profiles');
    const profiles = Array.isArray(profilesData) ? profilesData : profilesData?.profiles || [];
    if (!profiles.some(profile => String(profile?.id || '') === id)) {
      return res.status(400).json({ error: 'NextDNS ID không thuộc tài khoản của API key này.' });
    }

    const allowResult = await updateNextDnsList(apiKey, id, 'allowlist', allow);
    const denyResult = await updateNextDnsList(apiKey, id, 'denylist', deny);
    const replaced = replaceMobileConfigIdentity(template, name, description, id);
    if (!replaced.nameReplaced || !replaced.descriptionReplaced) {
      return res.status(400).json({
        error: 'File mẫu không có PayloadDisplayName/PayloadDescription hoặc placeholder tương ứng.',
      });
    }
    if (!replaced.profileIdReplacements) {
      return res.status(400).json({
        error: 'Không tìm thấy vị trí NextDNS ID. Hãy dùng URL NextDNS hoặc placeholder {{NEXTDNS_ID}} trong file mẫu.',
      });
    }

    const downloadId = randomUUID();
    downloadStore.set(downloadId, {
      buf: Buffer.from(replaced.result, 'utf8'),
      filename: safeMobileConfigFilename(name),
      contentType: 'application/x-apple-aspen-config',
      licenseToken: req.headers.authorization.slice(7),
      // Cho phép tải lại trong thời gian hiệu lực nếu người dùng hủy hộp
      // thoại chia sẻ hoặc cần chọn lại "Lưu vào Tệp".
      oneTime: false,
      expiry: Date.now() + 5 * 60 * 1000,
    });
    res.json({
      ok: true,
      downloadId,
      name,
      profileId: id,
      allowlist: allowResult,
      denylist: denyResult,
      nextDnsRejected: {
        allowlist: allowResult.rejected,
        denylist: denyResult.rejected,
        total: allowResult.rejected.length + denyResult.rejected.length,
      },
      profileIdReplacements: replaced.profileIdReplacements,
    });
  } catch (error) {
    res.status(502).json({ error: error?.message || 'Không thể cập nhật NextDNS.' });
  }
});

app.get('/api/engine-config', requireLicense, (_req, res) => {
  // Chỉ trả metadata và giá trị màu hiện tại; template/offset/hex tìm kiếm vẫn ở server.
  res.json({ fields: readEngineConfig() });
});

// ── PATCH CHAMS FILE ──────────────────────────────────────────
// Client gửi file + các thay đổi màu; server giữ template và patch hoàn toàn ở đây.
app.post('/api/patch-chams', requireLicense, (req,res) => {
  const { fileBase64, colors, fileName } = req.body;
  if (!fileBase64) return res.status(400).json({ error:'Thiếu file cần patch' });
  if (!colors || typeof colors !== 'object') return res.status(400).json({ error:'Thiếu cấu hình màu' });

  let fileBuf;
  if (typeof fileBase64 !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(fileBase64)) {
    return res.status(400).json({ error:'File base64 không hợp lệ' });
  }
  try { fileBuf=Buffer.from(fileBase64,'base64'); } catch { return res.status(400).json({ error:'File base64 không hợp lệ' }); }
  if (!fileBuf.length || fileBuf.length > MAX_UPLOAD_BYTES) {
    return res.status(413).json({ error:`File vượt giới hạn ${Math.floor(MAX_UPLOAD_BYTES / 1024 / 1024)} MB` });
  }

  const buf=Buffer.from(fileBuf);
  const replacement = buildReplacementTemplate(colors);
  if (!replacement) return res.status(400).json({ error:'Cấu hình màu không hợp lệ' });
  const total=applyHexPatch(buf, EMBEDDED_FIND_HEX, replacement);

  addLog('Patch chams file',{keyVal:req.license.key.value,keyId:req.license.key.id,success:total>0?1:0,ip:getIp(req),message:total>0?total+' vị trí đã patch':'Không tìm thấy vị trí hex'});

  if (total===0) return res.status(422).json({ error:'Không tìm thấy vị trí Hex trong file. Kiểm tra lại file gốc!' });

  const outName=(fileName||'output').replace(/(.dat)?$/i,'')+'_JerryMod';
  const dlId=randomUUID();
  downloadStore.set(dlId,{
    buf,
    filename:outName,
    contentType:'application/octet-stream',
    licenseToken:req.headers.authorization.slice(7),
    expiry:Date.now()+5*60*1000,
  });
  res.json({ ok:true, downloadId:dlId, patchCount:total });
});

// ── Serve patched file ────────────────────────────────────────
app.get('/api/download/:id', (req,res) => {
  const entry=downloadStore.get(req.params.id);
  if (!entry||entry.expiry<Date.now()) { downloadStore.delete(req.params.id); return res.status(404).json({ error:'Link tải đã hết hạn' }); }
  const presentedToken = String(req.query.license || (req.headers.authorization || '').replace(/^Bearer\s+/i, ''));
  if (entry.licenseToken && !constantTimeEqual(presentedToken, entry.licenseToken)) {
    return res.status(401).json({ error:'Cần phiên key hợp lệ để tải file.' });
  }
  if (entry.oneTime !== false) downloadStore.delete(req.params.id);
  const safe=entry.filename.replace(/[^\x20-\x7E]/g,'_').replace(/["\\/]/g,'_');
  res.set({ 'Content-Type':entry.contentType || 'application/octet-stream', 'Content-Disposition':'attachment; filename="'+safe+'"; filename*=UTF-8\'\'' + encodeURIComponent(entry.filename), 'Cache-Control':'no-store' });
  res.send(entry.buf);
});

